enum class Small : uint8_t { A=1, B=2 };
enum class Large : long long { X=1 }; 

// Size implication: Small is 1 byte, Large is 8 bytes
size_t small_sz = sizeof(Small); 

void handle(int i);
void handle(uint8_t u);

Small s = Small::A;
// handle(s); // Error: enum class prevents implicit conversion

handle(static_cast<uint8_t>(s)); // Explicit match to uint8_t overload

// Conditional expression type deduction (often converts to int)
// '1' (int) dominates the Small's underlying type (uint8_t)
auto promoted_res = (true ? 1 : s); // Type is int
auto small_res = (false ? Small::B : s); // Type is Small
